public class LocaleUtils_countriesByLanguage_TriageGen0Test {



    @Test
    public void testCountriesByLanguage_WithExistingLanguageCode() {
        // Tests the branch: if (countries == null) is false (assuming it was cached in previous calls or is known)
        // Since we cannot easily reset the static map cCountriesByLanguage without reflection, 
        // we call it with a known valid language to populate the cache, then call it again.

        String lang = "en";
        List firstCall = LocaleUtils.countriesByLanguage(lang);
        List secondCall = LocaleUtils.countriesByLanguage(lang);

        assertNotNull(firstCall);
        // The second call should return the same cached list
        assertSame(firstCall, secondCall);
    }






}

