/**
 * Unit tests for LocaleUtils.countriesByLanguage
 */
public class LocaleUtils_countriesByLanguage_TriageGen0Test {





    @Test
    public void testCountriesByLanguage_WithValidLanguageCode() {
        // Tests the branch: if (countries == null) -> if (languageCode != null) is true
        // Tests the loop and the condition: languageCode.equals(locale.getLanguage()) 
        // && locale.getCountry().length() != 0 && locale.getVariant().length() == 0

        // "en" is a standard language with multiple locales (en_US, en_GB, etc.)
        List result = LocaleUtils.countriesByLanguage("en");

        assertNotNull(result);
        for (Object obj : result) {
            Locale locale = (Locale) obj;
            assertEquals("en", locale.getLanguage());
            assertNotEquals("", locale.getCountry());
            assertEquals("", locale.getVariant());
        }
    }




}

