import static org.junit.Assert.*;

/**
 * Unit tests for LocaleUtils.countriesByLanguage
 */
public class LocaleUtils_countriesByLanguage_TriageGen0Test {









    @Test(expected = UnsupportedOperationException.class)
    public void testCountriesByLanguage_ReturnsUnmodifiableList() {
        // Tests that the returned list is unmodifiable when newly created
        String lang = "fr";
        List result = LocaleUtils.countriesByLanguage(lang);

        if (!result.isEmpty()) {
            result.remove(0);
        } else {
            // If the list is empty, we try to add to trigger exception
            result.add(new Locale("fr", "FR"));
        }
    }
}
